"""Monthly totals from rows of {"date": "YYYY-MM-DD", "amount": "12.50"}."""
from collections import defaultdict


def summarize_months(rows):
    totals = defaultdict(float)
    for row in rows:
        totals[row["date"][:7]] += float(row["amount"])
    return dict(totals)

